; AEA PK-88 firmware, Release 23.AUG.91
; Z80 CPU at 4.9152 MHz
; ROM:  0x0000-0x7fff (this 32 KiB image)
; SRAM: 0x8000-0xffff (battery-backed settings and working memory)
;
; Disassembly boundaries come from Ghidra 12.1.3 recursive analysis.
; Strings are stored as defb bytes; the final character has bit 7 set.
; Generated by: make disassemble

SCC_A_CTRL: equ 0f0h ; Z8530 channel A control/status (Bell 202/AX.25)
SCC_A_DATA: equ 0f1h ; Z8530 channel A data
SCC_B_CTRL: equ 0f2h ; Z8530 channel B control/status (terminal serial)
SCC_B_DATA: equ 0f3h ; Z8530 channel B data
LED_LATCH:  equ 0f4h ; Octal D-latch driving front-panel indicator LEDs (active-low)
; LED_LATCH bit assignments (LSB to MSB, active-low):
;   bit 0: CONV  - System is in Converse Mode
;   bit 1: TRANS - System is in Transparent Mode
;   bit 2: CMD   - System is in Command Mode
;   bit 3: SEND  - Transmitter Push-to-Talk line is enabled
;   bit 4: DCD   - Data Carrier Detect
;   bit 5: STA   - Packet frame(s) unacknowledged
;   bit 6: CON   - Packet link is in connected state
;   bit 7: MULT  - Multiple Connection in progress

; ============================================================
; SRAM (0x8000-0xFFFF) equates — battery-backed settings & state
; ============================================================

; --- Checksum & validation ---
BBRAM_CHKSUM:      equ 0881dh ; Battery settings checksum (1 byte)
ROM_CHKSUM:        equ 08825h ; ROM checksum (1 byte)

