	defb 0ffh		;0023
	defb 0ffh		;0024
	defb 0ffh		;0025
	defb 0ffh		;0026
	defb 0ffh		;0027
block_0003_end:

; BLOCK 'block_0004' (start 0x0028 end 0x0032)
block_0004_start:
; NZ only when SRAM 0x80d6 bit 0 and 0x80d5 bit 0 are both set.
test_status_80d6_and_80d5:
	push hl			;0028
l0029h:
	ld hl,080d6h		;0029
	bit 0,(hl)		;002c
	jr nz,l0011h		;002e
shared_pop_hl_return:
