service_deferred_queue:
; Services descriptor 0x8fd8 and sets deferred-work flag 0x8013 bit 0.
	ld hl,08013h		;003b
	set 0,(hl)		;003e
l0040h:
	ld hl,08fd8h		;0040
	call list_is_empty		;0043
l0046h:
	jr z,l004eh		;0046
