translate_escape_character:
; Maps ESC to '$' when configuration bit 0x80ab.7 is set.
	cp 01bh		;0056
	ret nz			;0058
	push hl			;0059
	ld hl,080abh		;005a
	bit 7,(hl)		;005d
	pop hl			;005f
	ret z			;0060
	ld a,024h		;0061
l0063h:
	ret			;0063
